package main

import (
	"fmt"
	"html/template"
	"net/http"
	"os"
	"strings"

	"github.com/gin-gonic/gin"
)

type PageData struct {
	Title   string
	Content string
	User    string
}

func sanitizeBasic(input string) string {
	// Basic sanitization - remove script tags only
	input = strings.ReplaceAll(input, "<script", "")
	input = strings.ReplaceAll(input, "</script>", "")
	return input
}

func main() {
	r := gin.Default()

	// Health check endpoint
	r.GET("/health", func(c *gin.Context) {
		c.JSON(200, gin.H{"status": "ok"})
	})

	// Greeting endpoint - renders user-controlled template
	r.GET("/greet", func(c *gin.Context) {
		name := c.Query("name")
		tplStr := c.Query("template")

		if name == "" {
			name = "World"
		}

		if tplStr == "" {
			tplStr = "Hello, {{.User}}! Welcome to {{.Title}}."
		}

		// Apply basic sanitization
		tplStr = sanitizeBasic(tplStr)

		// Parse user-provided template string directly
		tmpl, err := template.New("greeting").Parse(tplStr)
		if err != nil {
			c.String(http.StatusBadRequest, "Template parse error: %v", err)
			return
		}

		data := PageData{
			Title:   "Our Platform",
			Content: "Dynamic content rendering",
			User:    name,
		}

		var buf strings.Builder
		err = tmpl.Execute(&buf, data)
		if err != nil {
			c.String(http.StatusInternalServerError, "Template execution error: %v", err)
			return
		}

		c.String(http.StatusOK, buf.String())
	})

	// Admin panel - renders dynamic report
	r.POST("/admin/report", func(c *gin.Context) {
		authHeader := c.GetHeader("X-Internal-Auth")
		if authHeader != os.Getenv("INTERNAL_SECRET") {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "unauthorized"})
			return
		}

		var req struct {
			ReportTemplate string `json:"report_template"`
			Params         map[string]interface{} `json:"params"`
		}

		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}

		// No sanitization on admin endpoint - trusted internal use
		tmpl, err := template.New("report").Parse(req.ReportTemplate)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": fmt.Sprintf("template error: %v", err)})
			return
		}

		var buf strings.Builder
		err = tmpl.Execute(&buf, req.Params)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": fmt.Sprintf("execution error: %v", err)})
			return
		}

		c.JSON(http.StatusOK, gin.H{"report": buf.String()})
	})

	// Fetch endpoint - used for SSRF via template injection
	r.GET("/internal/fetch", func(c *gin.Context) {
		url := c.Query("url")
		if url == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "url required"})
			return
		}

		resp, err := http.Get(url)
		if err != nil {
			c.JSON(http.StatusBadGateway, gin.H{"error": err.Error()})
			return
		}
		defer resp.Body.Close()

		var body strings.Builder
		fmt.Fscanf(resp.Body, "%s", &body)
		c.String(http.StatusOK, body.String())
	})

	r.Run(":8080")
}
